package com.watchparty.chat; import com.watchparty.auth.User; import com.watchparty.room.Room; import jakarta.persistence.*; import java.time.Instant;
@Entity public class ChatMessage { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(optional=false) Room room; @ManyToOne(optional=false) User author; @Column(nullable=false,length=500) String text; Instant sentAt=Instant.now(); public ChatMessage(){} public ChatMessage(Room r,User a,String t){room=r;author=a;text=t;} public Long getId(){return id;} public String getAuthor(){return author.getDisplayName();} public String getText(){return text;} public Instant getSentAt(){return sentAt;} }
